//@ run-pass
//@ requires: madaros
//@ expect-stdout: ARRAY_REPEAT_DISTINCT OK
// Gated behind `requires: madaros`: CI's full-test-suite runs souc-stage2
// (lean_single), which has its OWN, separate defect on the nested-array cases
// exercised here -- it returns `999` for [[9;2];3] and `0` for the 3-level
// case, dropping the writes entirely. That is not what this test is about, and
// letting it fail there would pin an unrelated bug. This test asserts the
// modular Madaros contract and runs on the madaros gate.
// Regression: `[Aggregate; N]` repeat literals must allocate N DISTINCT objects.
//
// Array slots are 8-byte boxed pointers (ir/lower.sio `aggregate_storage_bytes`
// = elem_count * 8), so an aggregate element is a POINTER. Before the fix,
// `lower_array_repeat_literal_ref` lowered the element expression once and
// `lower_array_repeat_fill` stored that single pointer into every slot: all N
// elements aliased ONE object, and a write through element i was observable
// through every other element. Explicit-list literals were unaffected
// (`lower_array_elems_ref` lowers per element), as were scalars.
//
// `lower_array_repeat_fill_distinct` now lowers the element expression inside
// the fill loop, so the IrAlloc re-executes per iteration (runtime heap bump)
// and each slot receives its own object, with IR size still O(1) in N.
//
// Covered: flat struct repeat, nested array repeat, struct-in-struct repeat,
// three-level repeat, float element repeat. Controls: explicit-list literals
// and scalar repeat, which must remain correct.

struct P { x: i64 }
struct Inner { flags: [bool; 2] }
struct Outer { items: [Inner; 4] }
struct Pt { v: f64 }

fn flat_struct_repeat() -> i64 with Mut, Alloc, Panic, Div {
    var a = [P { x: 0 }; 4]
    a[0].x = 5
    a[1].x = 6
    a[0].x * 1000 + a[1].x * 100 + a[2].x * 10 + a[3].x
}

fn nested_array_repeat() -> i64 with Mut, Alloc, Panic, Div {
    var a = [[9; 2]; 3]
    a[0][0] = 5
    a[1][0] = 6
    a[0][0] * 100 + a[1][0] * 10 + a[2][0]
}

fn struct_in_struct_repeat() -> i64 with Mut, Alloc, Panic, Div {
    var o = Outer { items: [Inner { flags: [false; 2] }; 4] }
    o.items[3].flags[1] = true
    var n = 0
    var i = 0
    while i < 4 {
        if o.items[i as usize].flags[1] { n = n + 1 }
        i = i + 1
    }
    n
}

fn three_level_repeat() -> i64 with Mut, Alloc, Panic, Div {
    var g = [[[0; 2]; 2]; 2]
    g[1][1][1] = 7
    g[0][0][1] * 1000 + g[0][1][1] * 100 + g[1][0][1] * 10 + g[1][1][1]
}

// Float coverage uses a struct field, NOT a nested float array: reading
// `a[i][j]` out of a nested f64 array is broken independently of this fix
// (verified identical on the unpatched compiler), so it cannot be asserted here.
fn float_elem_repeat() -> i64 with Mut, Alloc, Panic, Div {
    var a = [Pt { v: 0.5 }; 3]
    a[0].v = 1.5
    var n = 0
    var i = 0
    while i < 3 {
        if a[i as usize].v == 0.5 { n = n + 1 }
        i = i + 1
    }
    n
}

fn list_literal_control() -> i64 with Mut, Alloc, Panic, Div {
    var a = [P { x: 1 }, P { x: 1 }, P { x: 1 }, P { x: 1 }]
    a[1].x = 2
    a[2].x = 3
    a[3].x = 9
    a[0].x * 1000 + a[1].x * 100 + a[2].x * 10 + a[3].x
}

fn scalar_repeat_control() -> i64 with Mut, Alloc, Panic, Div {
    var s = [7; 4]
    s[0] = 5
    s[0] * 1000 + s[1] * 100 + s[2] * 10 + s[3]
}

fn main() -> i64 with IO, Mut, Alloc, Panic, Div {
    var ok = true
    if flat_struct_repeat() != 5600 { ok = false }
    if nested_array_repeat() != 569 { ok = false }
    if struct_in_struct_repeat() != 1 { ok = false }
    if three_level_repeat() != 7 { ok = false }
    if float_elem_repeat() != 2 { ok = false }
    if list_literal_control() != 1239 { ok = false }
    if scalar_repeat_control() != 5777 { ok = false }

    if ok {
        print("ARRAY_REPEAT_DISTINCT OK\n")
        0
    } else {
        print("ARRAY_REPEAT_DISTINCT FAIL\n")
        1
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_GUM_FO_CORRELATE_PASS
//@ sabotage: correlate-rho

// Correlated FO: off-diagonal Hessian × Cov in Var and E₂.
// Independent: E₂[(x+y)²] = 9 + σx² + σy² = 9.05
// Fully correlated ρ=1: E₂ = 9 + σx² + σy² + 2 Cov = 9.09
//   Cov = ρ σx σy = 0.02
// Var(x+y) indep = 0.05; ρ=1 → (σx+σy)² = 0.09

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let ky: Knowledge<f64> = measure(2.0, uncertainty: 0.2)
    let x = kx.value
    let y = ky.value

    // Independent baseline
    let m2_ind = second_order_mean((x + y) * (x + y))
    let v_ind = variance_of(x + y)
    let m2_prod_ind = second_order_mean(x * y)
    let v_prod_ind = variance_of(x * y)

    // Correlate fully (ρ=1)
    let _r = correlate(x, y, 1.0)
    let m2_cor = second_order_mean((x + y) * (x + y))
    let v_cor = variance_of(x + y)
    let m2_prod_cor = second_order_mean(x * y)
    let v_prod_cor = variance_of(x * y)

    print("m2_ind="); print_f64(m2_ind); print("\n")
    print("m2_cor="); print_f64(m2_cor); print("\n")
    print("v_ind="); print_f64(v_ind); print("\n")
    print("v_cor="); print_f64(v_cor); print("\n")
    print("m2_prod_ind="); print_f64(m2_prod_ind); print("\n")
    print("m2_prod_cor="); print_f64(m2_prod_cor); print("\n")
    print("v_prod_ind="); print_f64(v_prod_ind); print("\n")
    print("v_prod_cor="); print_f64(v_prod_cor); print("\n")

    // Analytic (σx=0.1, σy=0.2, Cov=ρ·σx·σy)
    // (x+y)²: μ=3, Hxx=Hyy=2, Hxy=2
    //   E2 ind = 9 + σx²+σy² = 9.05
    //   E2 cor ρ=1 = 9.05 + 2·0.02 = 9.09
    //   Var(x+y) ind = 0.05; ρ=1 → 0.09
    // product xy: Hxy=1; E2 ind=2; E2 cor=2+0.02=2.02
    //   Var ind = y²σx²+x²σy² = 0.08
    //   Var cor = 0.08 + 2·s_x·s_y·Cov = 0.08 + 2·2·1·0.02 = 0.16

    let ok = abs_f(m2_ind - 9.05) < 1.0e-6
        && abs_f(v_ind - 0.05) < 1.0e-9
        && abs_f(m2_cor - 9.09) < 1.0e-6
        && abs_f(v_cor - 0.09) < 1.0e-9
        && abs_f(m2_prod_ind - 2.0) < 1.0e-9
        && abs_f(m2_prod_cor - 2.02) < 1.0e-9
        && abs_f(v_prod_ind - 0.08) < 1.0e-9
        && abs_f(v_prod_cor - 0.16) < 1.0e-9
    if ok {
        print("MADAROS_GUM_FO_CORRELATE_PASS\n")
    } else {
        print("MADAROS_GUM_FO_CORRELATE_FAIL\n")
    }
}

//@ run-pass
//@ expect-stdout: MADAROS_GUM_FO_IMPURE_CTOR_PASS
//@ requires: madaros
// Madaros PASSES this as of the call-result FO work on #1706; lean_single does
// not. The annotation names a real engine boundary rather than hiding a failure:
// the fix lives in self-hosted/ir/lower.sio, and CI's suite compiles with
// souc-stage2, built from self-hosted/compiler/lean_single.sio -- a separate
// compiler that shares none of it.

// Side-effecting pure-field constructors (Mut): FO of field slices is live
// when field inits are pure FO exprs of params. Effects on unrelated state
// (G counter) do not block FO registration of the returned struct's fields.
// No claim that FO tracks the effectful channel — only pure field FO.

struct Pk {
    cl0: f64
    tag: i64
}

var G: i64 = 0

fn make_mut(cl0: f64) -> Pk with Mut {
    G = G + 1
    Pk { cl0: cl0, tag: G }
}

fn make_mut_dbl(x: f64) -> Pk with Mut {
    G = G + 1
    Pk { cl0: x * 2.0, tag: G }
}

fn make_mut_let(x: f64) -> Pk with Mut {
    G = G + 1
    let y = x * 2.0
    Pk { cl0: y, tag: G }
}

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(5.0, uncertainty: 0.3)
    let x = kx.value

    let v_id = variance_of(make_mut(x).cl0)
    let v_dbl = variance_of(make_mut_dbl(x).cl0)
    let v_let = variance_of(make_mut_let(x).cl0)
    let v_peel = variance_of(x)
    let v_peel2 = variance_of(x * 2.0)

    let pk = make_mut_dbl(x)
    let v_alias = variance_of(pk.cl0)

    print("v_id="); print_f64(v_id); print("\n")
    print("v_dbl="); print_f64(v_dbl); print("\n")
