            if r == 12 { ax = assigned }
            if r == 21 { ay = assigned }
            if r == 22 { ay = assigned }
            if r == 31 { az = assigned }
            if r == 32 { az = assigned }
        }
        step = step + 1
    }
    return 0
}

fn check_rup_empty(h0: i64, h1: i64, hlen: i64, added5: i64, added6: i64) -> i64 {
    if hlen != 2 { return 0 }
    var ax: i64 = 0
    var ay: i64 = 0
    var az: i64 = 0
    var step: i64 = 0
    while step < hlen {
        var id = h0
        if step == 1 { id = h1 }
